changeSet.sql:
DO $$
DECLARE pending text;
BEGIN
  SELECT string_agg(id::text || ' (' || state || ')', ', ' ORDER BY created_at, id) INTO pending
  FROM public.person_data_request WHERE state IN ('ERASING', 'FAILED');
  IF pending IS NOT NULL THEN
    RAISE EXCEPTION E'The upgrade stopped before copied identities leave the review item detail. These person data erasures are admitted and not complete: %\nKeep the new release stopped and follow "Recover when the migration stops on an erasure" in the migration guide entry "Stop every role before copied identities leave the review item detail": https://github.com/hephaestus-build/Hephaestus/blob/main/MIGRATION.md', pending;
  END IF;
END $$
